sp_widget.client_script:
api.controller = function($scope, $interval) {
  var c = this;

  c.currentIndex = 0;

  c.next = function() {
    c.currentIndex = (c.currentIndex + 1) % $scope.data.images.length;
  };

  c.prev = function() {
    c.currentIndex = (c.currentIndex - 1 + $scope.data.images.length) % $scope.data.images.length;
  };

  // Autoplay
  $interval(c.next, 5000);
};

sp_widget.css:
.carousel-container {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: 16px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25);
  background-color: #f8f8f8;
  transition: height 0.4s ease;
}

.carousel-slide {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.carousel-image {
  max-width: 100%;
  height: auto;
  border-radius: 16px;
  display: block;
  transition: opacity 0.6s ease;
}

.carousel-controls {
  position: absolute;
  top: 50%;
  width: 100%;
  display: flex;
  justify-content: space-between;
  transform: translateY(-50%);
  padding: 0 20px;
  pointer-events: none;
}

.carousel-controls button {
  background-color: rgba(0, 0, 0, 0.6);
  color: white;
  border: none;
  font-size: 28px;
  cursor: pointer;
  pointer-events: all;
  padding: 10px 14px;
  border-radius: 50%;
  transition: background-color 0.3s ease;
}

.carousel-controls button:hover {
  background-color: rgba(0, 0, 0, 0.8);
}

